-- The city lives once, in dbo.Customers; the report is derived
CREATE VIEW dbo.RevenueByCity WITH SCHEMABINDING AS
SELECT c.City, SUM(o.Total) AS Revenue, COUNT_BIG(*) AS Orders
FROM dbo.Orders AS o JOIN dbo.Customers AS c ON c.Id = o.CustomerId
GROUP BY c.City;
GO
CREATE UNIQUE CLUSTERED INDEX IX_RevenueByCity ON dbo.RevenueByCity (City);

UPDATE dbo.Customers SET City = N'Alexandria' WHERE Id = 165;
